76	
77	  const [formProduto, setFormProduto] = useState("");
78	  const [formNcm, setFormNcm] = useState("");
79	  const [formCategoria, setFormCategoria] = useState<Categoria>("insumos");
80	  const [formDescricao, setFormDescricao] = useState("");
81	  const [formCusto, setFormCusto] = useState("");
82	  const fileInputRef = useRef<HTMLInputElement>(null);
83	  const { canViewNCM } = usePermissions();
84	  const hasAccess = canViewNCM();
85	
86	  useMiaNCMActions({
