94	
95	  const fetchItems = async () => {
96	    try {
97	      setLoading(true);
98	      const { data, error } = await supabase
99	        .from("ncm_produtos")
100	        .select("*")
101	        .order("produto_nome", { ascending: true });
102	      if (error) throw error;
103	      const arr = (data || []) as NcmProduto[];
104	      const dedup = new Map<string, NcmProduto>();
105	      for (const it of arr) {
106	        const existing = dedup.get(it.produto_nome);
107	        if (!existing || (!existing.ncm && it.ncm)) {
108	          dedup.set(it.produto_nome, it);
109	        }
110	      }
111	      setItems(Array.from(dedup.values()));
112	    } catch (error) {
113	      console.error("Erro ao buscar NCMs:", error);
114	      toast({ title: "Erro ao carregar", description: "Não foi possível carregar os NCMs" });
115	    } finally {
116	      setLoading(false);
117	    }
118	  };
119	
120	  const filteredItems = useMemo(() => {
121	    const filtered = items
122	      .filter((it) => categoriaFilter === "all" || it.categoria === categoriaFilter)
123	      .filter((it) => (ncmFilter === "all" ? true : ncmFilter === "com" ? Boolean(it.ncm) : !it.ncm))
124	      .filter((it) =>
125	        searchTerm ? it.produto_nome.toLowerCase().includes(searchTerm.toLowerCase()) || (it.ncm || "").includes(searchTerm) : true
126	      );
127	
128	    const dedup = new Map<string, NcmProduto>();
129	    for (const it of filtered) {
130	      const prev = dedup.get(it.produto_nome);
131	      if (!prev || (!prev.ncm && it.ncm)) dedup.set(it.produto_nome, it);
132	    }
133	    return Array.from(dedup.values());
134	  }, [items, categoriaFilter, ncmFilter, searchTerm]);
135	
136	  const handlePrint = () => {
137	    try {
138	      const ordered: Categoria[] = [
139	        'insumos',
140	        'embalagens',
141	        'descartaveis',
142	        'bebidas',
143	        'mercearia',
144	        'material_limpeza',
145	        'insumos_momma_brunch',
146	        'finalizados',
147	      ];
148	
149	      const map = new Map<Categoria, NcmProduto[]>();
150	      for (const it of filteredItems) {
