236	          .page { page-break-after: always; break-after: page; }
237	          .page:last-child { page-break-after: auto; break-after: auto; }
238	          @media print { body { -webkit-print-color-adjust: exact; } }
239	        </style>
240	      </head>
241	      <body>
242	        <div class="header"><span class="header-title">MOMMA DOCES SAUDÁVEIS</span></div>
243	        ${pagesHtml}
244	      </body>
245	      </html>`;
246	
247	      printHTML(html, { title: 'NCMs - Momma' });
248	    } catch (e) { console.error(e); }
249	  };
