431	        </div>
432	      </div>
433	
434	      <Card>
435	        <CardHeader>
436	          <CardTitle className="flex items-center gap-2 text-lg">
437	            <FileText className="h-5 w-5" /> Lista de NCMs
438	          </CardTitle>
439	        </CardHeader>
440	        <CardContent>
441	          <div className="grid grid-cols-1 md:grid-cols-4 gap-3 mb-4">
442	            <div>
443	              <Label className="text-xs">Filtrar por categoria</Label>
444	              <Select value={categoriaFilter} onValueChange={(v) => setCategoriaFilter(v as Categoria | "all")}>
445	                <SelectTrigger className="h-8">
446	                  <SelectValue placeholder="Todas" />
447	                </SelectTrigger>
448	                <SelectContent>
449	                  <SelectItem value="all">Todas</SelectItem>
450	                  <SelectItem value="insumos">Insumos</SelectItem>
451	                  <SelectItem value="embalagens">Embalagens</SelectItem>
452	                  <SelectItem value="descartaveis">Descartáveis</SelectItem>
453	                  <SelectItem value="bebidas">Bebidas</SelectItem>
454	                  <SelectItem value="mercearia">Mercearia</SelectItem>
455	                  <SelectItem value="material_limpeza">Material de Limpeza</SelectItem>
456	                  <SelectItem value="insumos_momma_brunch">Insumos Momma Brunch</SelectItem>
457	                </SelectContent>
458	              </Select>
459	            </div>
460	            <div>
461	              <Label className="text-xs">Filtrar por NCM</Label>
462	              <Select value={ncmFilter} onValueChange={(v) => setNcmFilter(v as "all" | "com" | "sem")}>
463	                <SelectTrigger className="h-8">
