66	export const cmvNodeId = (id: number) => `cmv_${id}`;
67	export const fichaNodeId = (id: number) => `ficha_${id}`;
68	export const insumoNodeId = (id: number) => `insumo_${id}`;
69	export const nfNodeId = (id: number) => `nf_${id}`;
